+            // Create PartBunch with a single particle container.
+            bunch = std::make_shared<PartBunch_t>(
+                std::vector<double>{1.0},
+                std::vector<double>{1.0},
+                std::vector<Beam*>{testBeam},
+                std::vector<size_t>{1},
